INSERT INTO battle_phases (id, event_id, seq, name, period, start_precision, end_precision, summary, status) VALUES ('c9b31a0c-ee57-5d1c-8a7e-abb837c05887', '93397ce5-a52b-5537-b839-10ac0a4e1743', 1, '{"zh-Hant": "進攻與突破"}'::jsonb, '[1939-09-01,1939-09-07)'::daterange, 'day', 'day', '{"zh-Hant": "德軍9月1日越境，北方集團軍群3日切斷波蘭走廊，南方集團軍群渡過瓦爾塔河並攻佔琴斯托霍瓦。"}'::jsonb, 'pending');
INSERT INTO battle_phase_citations (id, phase_id, source_id, locator, quote, quote_lang, evidence_note, accessed_on, grade, policy_version) VALUES ('bdccd22b-d5bc-56f3-8eb8-d0e55c0cee07', 'c9b31a0c-ee57-5d1c-8a7e-abb837c05887', '365dc72d-9c45-58b1-941a-109db98ccf8e', 'p. 85 (HyperWar Campaign-III.html)', 'Czestochowa was taken on the morning of 3 September', 'en', '階段引文：Kennedy 單一來源家族，A 降 B', '2026-11-13', 'B', 'battle-db-2026-11-13');
INSERT INTO battle_phases (id, event_id, seq, name, period, start_precision, end_precision, summary, status) VALUES ('0317dd90-fb6d-5a38-9e6d-e11e6f6c8522', '93397ce5-a52b-5537-b839-10ac0a4e1743', 2, '{"zh-Hant": "殲滅波軍主力（布祖拉／拉多姆）"}'::jsonb, '[1939-09-07,1939-09-17)'::daterange, 'day', 'day', '{"zh-Hant": "德軍於拉多姆殲滅波軍一部，並將西部波軍殘部圍困於庫特諾與華沙之間，北翼第19軍渡納雷夫河直趨布列斯特。"}'::jsonb, 'pending');
INSERT INTO battle_phases (id, event_id, seq, name, period, start_precision, end_precision, summary, status) VALUES ('e990aa68-db6e-5fc0-b7a3-e33f6223bbe8', '93397ce5-a52b-5537-b839-10ac0a4e1743', 3, '{"zh-Hant": "蘇聯入侵與華沙投降"}'::jsonb, '[1939-09-17,1939-09-28)'::daterange, 'day', 'day', '{"zh-Hant": "9月17日紅軍進入波蘭東部，德軍止步於布格河—布列斯特—比亞韋斯托克一線並於22日將布列斯特移交紅軍，華沙於27日投降。"}'::jsonb, 'pending');
INSERT INTO battle_phase_citations (id, phase_id, source_id, locator, quote, quote_lang, evidence_note, accessed_on, grade, policy_version) VALUES ('c5c38e9c-558e-547a-9c46-a5a7035eb2a4', 'e990aa68-db6e-5fc0-b7a3-e33f6223bbe8', '365dc72d-9c45-58b1-941a-109db98ccf8e', 'p. 99 (HyperWar Campaign-III.html)', 'directed to remain west of the line along the Bug River-Brzesc-Bialystok.', 'en', '階段引文：Kennedy 單一來源家族，A 降 B', '2026-11-13', 'B', 'battle-db-2026-11-13');
INSERT INTO battle_phase_citations (id, phase_id, source_id, locator, quote, quote_lang, evidence_note, accessed_on, grade, policy_version) VALUES ('1104d11f-dec6-5679-9849-fc6f6232954b', 'e990aa68-db6e-5fc0-b7a3-e33f6223bbe8', '365dc72d-9c45-58b1-941a-109db98ccf8e', 'p. 117 (HyperWar Campaign-III.html)', 'The XIX Corps turned Brzesc over to the Red Army on 22 September', 'en', '階段引文：Kennedy 單一來源家族，A 降 B', '2026-11-13', 'B', 'battle-db-2026-11-13');
INSERT INTO battle_phases (id, event_id, seq, name, period, start_precision, end_precision, summary, status) VALUES ('f2fc021d-53a8-52ca-b777-8ad723f55ba7', '93397ce5-a52b-5537-b839-10ac0a4e1743', 4, '{"zh-Hant": "最後抵抗：莫德林、海爾、科克"}'::jsonb, '[1939-09-28,1939-10-07)'::daterange, 'day', 'day', '{"zh-Hant": "莫德林於9月29日投降，海爾半島守軍10月1日請求談判，波軍最後一支主力於10月4至6日在科克作戰後投降。"}'::jsonb, 'pending');
